let activeCall = null, callPeer = null, localCallStream = null, callStartedAt = 0, callTimer = null, ringTimer = null, ringContext = null, callTimeout = null, pendingIceCandidates = [], rtcConfig = { iceServers: [{ urls: 'stun:stun.l.google.com:19302' }] };
const money = n => '₦' + Number(n || 0).toLocaleString('en-NG');
