const timeAgo = date => { const m = Math.floor((Date.now()-new Date(date))/60000); return m<1?'now':m<60?`${m}m`:m<1440?`${Math.floor(m/60)}h`:`${Math.floor(m/1440)}d`; };
async function api(url, options={}) {
  const opts = { credentials:'same-origin', ...options, headers:{ ...(options.body instanceof FormData ? {} : {'Content-Type':'application/json'}), ...(options.headers||{}) } };
  if (opts.body && !(opts.body instanceof FormData) && typeof opts.body !== 'string') opts.body = JSON.stringify(opts.body);
  const r = await fetch('/api'+url, opts); const data = await r.json().catch(()=>({}));
  if (!r.ok) throw new Error(data.error || 'Something went wrong.');
  return data;
}
// XMLHttpRequest is used for multipart uploads so the interface can show real upload progress.
function uploadApi(url, formData, onProgress=()=>{}, method='POST') {
  return new Promise((resolve,reject)=>{
    const xhr=new XMLHttpRequest(); xhr.open(method,'/api'+url); xhr.withCredentials=true;
    xhr.upload.addEventListener('progress',e=>{if(e.lengthComputable)onProgress(Math.min(100,Math.round(e.loaded/e.total*100)))});
    xhr.addEventListener('load',()=>{let data={};try{data=JSON.parse(xhr.responseText||'{}')}catch{};if(xhr.status>=200&&xhr.status<300)resolve(data);else reject(new Error(data.error||`Upload failed (${xhr.status}).`))});
    xhr.addEventListener('error',()=>reject(new Error('Network error during upload. Check your connection and try again.')));
    xhr.addEventListener('timeout',()=>reject(new Error('Upload timed out. Try a smaller file or a stronger connection.')));
    xhr.timeout=10*60*1000; xhr.send(formData);
  });
}
function setUploadProgress(node,percent,label='Uploading') { if(!node)return; node.classList.remove('hidden'); node.innerHTML=`<div class="upload-progress-label"><span>${esc(label)}</span><b>${percent}%</b></div><div class="upload-progress-track"><span style="width:${percent}%"></span></div>`; }
function toast(msg){ const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2800); }

function applyPlatformName(name='CHATHIS'){
  const safe=String(name||'CHATHIS').slice(0,32);
  document.querySelectorAll('.brand-name,.mobile-brand .brand-name').forEach(el=>el.textContent=safe);
  document.querySelectorAll('.brand').forEach(el=>{const n=el.querySelector('.brand-name');if(n)n.textContent=safe;});
  document.title=`${safe} — Connect. Express. Belong.`;
}

function applyAppearance(a={}){
  activeAppearance=a;
  const root=document.documentElement;
  const primary=/^#[0-9a-f]{6}$/i.test(a.primary||'')?a.primary:'#2878f0';
  const secondary=/^#[0-9a-f]{6}$/i.test(a.secondary||'')?a.secondary:'#4c9bff';
  root.style.setProperty('--blue',primary);root.style.setProperty('--blue2',secondary);
  root.style.setProperty('--pale',`${primary}18`);
  if(/^#[0-9a-f]{6}$/i.test(a.background||''))document.body.style.setProperty('--bg',a.background);
  if(/^#[0-9a-f]{6}$/i.test(a.surface||''))document.body.style.setProperty('--surface',a.surface);
  if(/^#[0-9a-f]{6}$/i.test(a.text||''))document.body.style.setProperty('--ink',a.text);
  document.body.dataset.theme=['dark','midnight','rose'].includes(a.mode)?a.mode:'light';
  let banner=document.getElementById('eventDecoration');
  const events={celebration:['🎉','✨','🎊'],'christmas':['🎄','❄️','🎁'],'valentine':['💗','🌹','💕'],'halloween':['🎃','🦇','✨'],'newyear':['🎆','🥂','✨'],'independence':['🇳🇬','💚','🤍']};
  const items=events[a.decoration]||[];
  if(!banner){banner=document.createElement('div');banner.id='eventDecoration';banner.className='event-decoration';const app=$('#appView');if(app)app.prepend(banner)}
  banner.classList.toggle('hidden',!items.length);
  if(items.length)banner.innerHTML=`<span aria-hidden="true">${items.join(' ')}</span><b>${esc(a.eventLabel||'')}</b><span aria-hidden="true">${items.slice().reverse().join(' ')}</span>`;
}
function openModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden');}
function closeModal(){$('#modal').classList.add('hidden');}
document.addEventListener('click',e=>{if(e.target.matches('[data-close]'))closeModal();const p=e.target.closest('[data-page]');if(p){e.preventDefault();navigate(p.dataset.page)}});
function setAuthTab(tab){$$('.auth-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.auth===tab));$('#loginForm').classList.toggle('hidden',tab!=='login');$('#registerForm').classList.toggle('hidden',tab!=='register');}
$$('.auth-tabs button').forEach(b=>b.addEventListener('click',()=>setAuthTab(b.dataset.auth)));
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await api('/auth/login',{method:'POST',body:d});await boot();}catch(err){toast(err.message)}});
$('#registerForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await api('/auth/register',{method:'POST',body:d});await boot();}catch(err){toast(err.message)}});
$('#logoutBtn').addEventListener('click',async()=>{await api('/auth/logout',{method:'POST'});if(socket)socket.disconnect();me=null;$('#appView').classList.add('hidden');$('#authView').classList.remove('hidden')});
$('#year').textContent=new Date().getFullYear();
async function boot(){try{const d=await api('/me');me=d.user;$('#authView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#adminNav').classList.toggle('hidden',me.role!=='admin');$('#adminMobileNav')?.classList.toggle('hidden',me.role!=='admin');$('#meMini').textContent='@'+me.username;const config=await api('/config');applyAppearance(config.appearance||{});applyPlatformName(config.platform?.name||'CHATHIS');connectSocket();await fetchRtcConfig();await loadSuggestions();navigate(location.pathname==='/admin'?'admin':'feed')}catch{$('#appView').classList.add('hidden');$('#authView').classList.remove('hidden')}}
function connectSocket(){if(socket)socket.disconnect();socket=io({auth:{}});socket.on('connect',()=>{});socket.on('presence:update',event=>applyPresence(event));socket.on('appearance:updated', appearance=>applyAppearance(appearance));
  // Server broadcasts these events after successful writes. Refresh the visible feed quietly,
  // preserving an in-progress composer draft and the selected feed filter.
  let liveRefreshRunning=false, liveRefreshQueued=false;
  const refreshVisibleFeed=async()=>{if(currentPage!=='feed')return;if(liveRefreshRunning){liveRefreshQueued=true;return}liveRefreshRunning=true;try{const draft=$('#postForm textarea')?.value||'';const filter=$('#feedFilter')?.value||'all';const scroll=window.scrollY;await renderFeed();const composer=$('#postForm textarea');if(composer)composer.value=draft;const picker=$('#feedFilter');if(picker){picker.value=filter;renderFilteredPosts(filter)}window.scrollTo(0,scroll)}catch(e){console.warn('Live feed refresh failed:',e.message)}finally{liveRefreshRunning=false;if(liveRefreshQueued){liveRefreshQueued=false;refreshVisibleFeed()}}};
  socket.on('feed:refresh',()=>refreshVisibleFeed());
  socket.on('story:created',()=>refreshVisibleFeed());
  socket.on('profile:updated',event=>{if(event?.user?.id&&String(event.user.id)===String(me?.id))return;if(currentPage==='feed')refreshVisibleFeed();if(currentPage==='messages')renderMessages().catch(()=>{})});
  socket.on('notification',()=>{if(currentPage==='notifications')renderNotifications()});socket.on('friend:request',()=>{if(currentPage==='explore')renderExplore();toast('You received a friend request.')});socket.on('friend:updated',()=>{if(currentPage==='explore')renderExplore()});socket.on('group:updated',async event=>{if(currentPage==='messages'){if(activeGroupId&&String(event?.groupId)===activeGroupId){try{const list=await api('/groups');if(!(list.groups||[]).some(g=>String(g.id)===activeGroupId))activeGroupId=null;}catch{activeGroupId=null}}renderMessages().catch(()=>{})}});socket.on('group:message',m=>{if(currentPage==='messages'&&activeGroupId===String(m.group))renderGroupMessages(activeGroupId);else if(currentPage!=='messages')toast('New group message received')});socket.on('message',m=>{const otherId=String(m.sender?._id||m.sender||'');if(currentPage==='messages'){if(activeChat===otherId)renderChatMessages(activeChat);renderMessages().then(()=>{if(activeChat)renderChatMessages(activeChat)}).catch(()=>{});}else toast('New message received')});
  socket.on('call:invite', data=>showIncomingCall(data));
  socket.on('call:accept', async data=>{if(activeCall?.role==='caller'&&data.from===activeCall.peerId){try{stopRingtone();const offer=await callPeer.createOffer();await callPeer.setLocalDescription(offer);socket.emit('call:offer',{recipientId:activeCall.peerId,offer});}catch(e){toast('Could not start call: '+e.message);endCall(false)}}});
  socket.on('call:reject', data=>{if(activeCall?.peerId===data.from){toast('Call declined.');endCall(false)}});
  socket.on('call:end', data=>{if(activeCall?.peerId===data.from){toast('Call ended.');endCall(false)}});
  socket.on('call:offer', async data=>{if(!activeCall||activeCall.peerId!==data.from)return;try{await callPeer.setRemoteDescription(new RTCSessionDescription(data.offer));await flushPendingIce();const answer=await callPeer.createAnswer();await callPeer.setLocalDescription(answer);socket.emit('call:answer',{recipientId:data.from,answer})}catch(e){toast('Call connection failed.');endCall(false)}});
  socket.on('call:answer', async data=>{if(activeCall?.peerId===data.from&&callPeer)try{await callPeer.setRemoteDescription(new RTCSessionDescription(data.answer));await flushPendingIce()}catch(e){toast('Could not establish call.');endCall(false)}});
  socket.on('call:ice', async data=>{if(activeCall?.peerId===data.from&&callPeer&&data.candidate){if(!callPeer.remoteDescription){pendingIceCandidates.push(data.candidate);return}try{await callPeer.addIceCandidate(new RTCIceCandidate(data.candidate))}catch(e){console.warn('ICE candidate rejected:',e.message)}}});
}
function statusMarkup(isOnline){return `<span class="presence-label ${isOnline?'is-online':'is-offline'}"><i class="presence-dot"></i>${isOnline?'Online':'Offline'}</span>`}
function applyPresence(event){if(!event?.userId)return;const online=!!event.online;document.querySelectorAll('[data-user-status]').forEach(el=>{if(el.dataset.userStatus===String(event.userId)){el.className=`presence-label ${online?'is-online':'is-offline'}`;el.innerHTML=`<i class="presence-dot"></i>${online?'Online':'Offline'}`}});}
async function fetchRtcConfig(){try{const c=await api('/config');if(c.rtc?.iceServers?.length)rtcConfig=c.rtc}catch{}}
function startRingtone(kind='incoming'){
  stopRingtone();
  try{
    const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;
    ringContext=new AudioCtx();ringContext.resume().catch(()=>{});
    const playPair=()=>{if(!ringContext||ringContext.state==='closed')return;const now=ringContext.currentTime;[0,kind==='incoming'?0.22:0.28].forEach((offset,i)=>{const osc=ringContext.createOscillator(),gain=ringContext.createGain();osc.type='sine';osc.frequency.value=kind==='incoming'?(i?660:880):(i?480:620);gain.gain.setValueAtTime(0.0001,now+offset);gain.gain.exponentialRampToValueAtTime(0.12,now+offset+0.025);gain.gain.exponentialRampToValueAtTime(0.0001,now+offset+0.17);osc.connect(gain);gain.connect(ringContext.destination);osc.start(now+offset);osc.stop(now+offset+0.19)})};
    playPair();ringTimer=setInterval(playPair,kind==='incoming'?1450:1900);
  }catch(err){console.warn('Ringtone unavailable:',err.message)}
}
function stopRingtone(){if(ringTimer)clearInterval(ringTimer);ringTimer=null;if(ringContext){const ctx=ringContext;ringContext=null;ctx.close().catch(()=>{})}}
async function createPeerConnection(peerId){
  pendingIceCandidates=[];callPeer=new RTCPeerConnection(rtcConfig);
  callPeer.onicecandidate=e=>{if(e.candidate&&socket)socket.emit('call:ice',{recipientId:peerId,candidate:e.candidate})};
  callPeer.ontrack=e=>{
    const stream=e.streams[0];
    if(activeCall?.callType==='video'){
      let video=document.getElementById('remoteCallVideoPreview');if(!video){video=document.createElement('video');video.id='remoteCallVideo';video.autoplay=true;video.playsInline=true;video.className='remote-call-video';document.body.appendChild(video)}video.srcObject=stream;video.play().catch(()=>{});
    }else{
      let audio=document.getElementById('remoteCallAudio');if(!audio){audio=document.createElement('audio');audio.id='remoteCallAudio';audio.autoplay=true;document.body.appendChild(audio)}audio.srcObject=stream;audio.play().catch(()=>{});
    }
  };
  callPeer.onconnectionstatechange=()=>{if(!callPeer||!activeCall)return;if(callPeer.connectionState==='connected'){startCallClock()}else if(callPeer.connectionState==='failed'){toast('Call connection failed. Check your network or TURN configuration.');endCall(true)}else if(callPeer.connectionState==='disconnected'){toast('Call connection interrupted. Trying to reconnect…')}};
}
async function startCall(user,callType='audio'){
  if(activeCall)return toast('You are already in a call.');
  if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)return toast('Calls need a supported browser and HTTPS.');
  try{
    await fetchRtcConfig();localCallStream=await navigator.mediaDevices.getUserMedia({audio:true,video:callType==='video'});
    activeCall={peerId:String(user.id),peerName:user.username,role:'caller',callType};
    await createPeerConnection(user.id);localCallStream.getTracks().forEach(t=>callPeer.addTrack(t,localCallStream));
    showCallPanel(`Calling @${user.username}…`);startRingtone('outgoing');
    socket.emit('call:invite',{recipientId:user.id,callerName:me.username,callType});callTimeout=setTimeout(()=>{if(activeCall?.role==='caller'){toast('No answer. Call ended.');endCall(true)}},45000);
  }catch(e){toast(e.name==='NotAllowedError'?'Allow camera and microphone access to make this call.':e.message);endCall(false)}
}
function showIncomingCall(data){
  if(activeCall){socket.emit('call:reject',{recipientId:data.from});return}
  stopRingtone();activeCall={peerId:String(data.from),peerName:data.callerName||'CHATHSI member',role:'callee',incoming:true,callType:data.callType==='video'?'video':'audio'};
  startRingtone('incoming');callTimeout=setTimeout(()=>{if(activeCall?.incoming){socket.emit('call:reject',{recipientId:activeCall.peerId});closeModal();endCall(false)}},45000);openModal(`<h2>Incoming ${activeCall.callType==='video'?'video':'voice'} call</h2><p>@${esc(activeCall.peerName)} is calling you.</p><div class="call-actions"><button class="btn primary" id="acceptCall">Accept</button><button class="btn subtle-btn" id="declineCall">Decline</button></div>`);
  $('#acceptCall').onclick=async()=>{if(callTimeout)clearTimeout(callTimeout);callTimeout=null;stopRingtone();closeModal();try{await fetchRtcConfig();localCallStream=await navigator.mediaDevices.getUserMedia({audio:true,video:activeCall.callType==='video'});await createPeerConnection(activeCall.peerId);localCallStream.getTracks().forEach(t=>callPeer.addTrack(t,localCallStream));activeCall.incoming=false;showCallPanel(`Connecting to @${activeCall.peerName}…`);socket.emit('call:accept',{recipientId:activeCall.peerId,callType:activeCall.callType});callTimeout=setTimeout(()=>{if(activeCall){toast('Could not connect the call. Please try again.');endCall(true)}},45000)}catch(e){toast(e.name==='NotAllowedError'?'Allow camera and microphone access to accept this call.':e.message);socket.emit('call:reject',{recipientId:activeCall.peerId});endCall(false)}};
  $('#declineCall').onclick=()=>{if(callTimeout)clearTimeout(callTimeout);callTimeout=null;stopRingtone();socket.emit('call:reject',{recipientId:activeCall.peerId});closeModal();activeCall=null};
}
function showCallPanel(label){
  stopRingtone();let el=document.getElementById('callPanel');if(!el){el=document.createElement('div');el.id='callPanel';el.className='call-panel';document.body.appendChild(el)}
  const videoMarkup=activeCall?.callType==='video'?'<div class="call-video-grid"><video id="localCallVideo" autoplay muted playsinline></video><video id="remoteCallVideoPreview" autoplay playsinline></video></div>':'';
  el.innerHTML=`<div class="call-panel-content"><b>CHATHSI ${activeCall?.callType==='video'?'Video':'Voice'} call</b><small id="callStatus">${esc(label)}</small>${videoMarkup}</div><div class="call-actions"><button id="muteCall" class="subtle-btn">Mute</button>${activeCall?.callType==='video'?'<button id="cameraCall" class="subtle-btn">Camera off</button>':''}<button id="endCall" class="btn danger">End call</button></div>`;
  if(activeCall?.callType==='video'&&localCallStream){const local=$('#localCallVideo');if(local){local.srcObject=localCallStream;local.play().catch(()=>{})}}
  $('#muteCall').onclick=()=>{const track=localCallStream?.getAudioTracks()[0];if(track){track.enabled=!track.enabled;$('#muteCall').textContent=track.enabled?'Mute':'Unmute'}};
  $('#cameraCall')?.addEventListener('click',()=>{const track=localCallStream?.getVideoTracks()[0];if(track){track.enabled=!track.enabled;$('#cameraCall').textContent=track.enabled?'Camera off':'Camera on'}});
  $('#endCall').onclick=()=>endCall(true);
}
async function flushPendingIce(){if(!callPeer?.remoteDescription||!pendingIceCandidates.length)return;const queued=pendingIceCandidates.splice(0);for(const candidate of queued){try{await callPeer.addIceCandidate(new RTCIceCandidate(candidate))}catch(e){console.warn('Queued ICE candidate rejected:',e.message)}}}
function startCallClock(){if(callStartedAt)return;if(callTimeout)clearTimeout(callTimeout);callTimeout=null;stopRingtone();callStartedAt=Date.now();if($('#callStatus'))$('#callStatus').textContent='Connected · 00:00';callTimer=setInterval(()=>{if($('#callStatus')){const sec=Math.floor((Date.now()-callStartedAt)/1000);$('#callStatus').textContent=`Connected · ${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}},1000)}
function endCall(notifyPeer=true){if(callTimeout)clearTimeout(callTimeout);callTimeout=null;stopRingtone();if(notifyPeer&&activeCall&&socket)socket.emit('call:end',{recipientId:activeCall.peerId});if(callTimer)clearInterval(callTimer);callTimer=null;callStartedAt=0;if(localCallStream)localCallStream.getTracks().forEach(t=>t.stop());localCallStream=null;if(callPeer){callPeer.close();callPeer=null}document.getElementById('remoteCallAudio')?.remove();document.getElementById('remoteCallVideo')?.remove();document.getElementById('callPanel')?.remove();pendingIceCandidates=[];activeCall=null}
async function navigate(page){currentPage=page;$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const pages={feed:renderFeed,explore:renderExplore,messages:renderMessages,notifications:renderNotifications,wallet:renderWallet,profile:renderProfile,premium:renderPremium,ads:renderAds,admin:renderAdmin};if(!pages[page])page='feed';try{await pages[page]()}catch(e){$('#page').innerHTML=`<div class="empty"><strong>Could not load this page</strong>${esc(e.message)}</div>`}}
async function loadSuggestions(){try{const d=await api('/users');cachedUsers=d.users;$('#suggestions').innerHTML=d.users.slice(0,4).map(u=>`<div class="suggestion">${avatar(u.avatar,u.username)}<div class="suggestion-info"><b>@${esc(u.username)}</b><small>${esc(u.displayName||'CHATHSI member')} · <span data-user-status="${esc(u.id)}">${statusMarkup(u.isOnline)}</span></small></div><button class="follow-btn" data-follow="${u.id}">Follow</button></div>`).join('')||'<div class="muted">You are all caught up.</div>'}catch{}}
async function renderFeed(){const [pd,sd,adData]=await Promise.all([api('/posts'),api('/stories'),api('/ads')]);window.chathsiStories=sd.stories||[];window.chathsiPosts=pd.posts||[];$('#page').innerHTML=`<div class="row-between"><div><h1 class="page-title">Your feed</h1><p class="page-sub">See what's happening in your circle.</p></div><button class="btn primary" id="newPostTop">＋ Create post</button></div>
<div class="story-strip"><button type="button" class="story-chip" id="addStory"><div class="story-ring"><div class="avatar">＋</div></div>Add story</button>${window.chathsiStories.slice(0,12).map((s,i)=>`<button type="button" class="story-chip" data-view-story="${i}"><div class="story-ring">${avatar(s.author?.avatar,s.author?.username)}</div>@${esc(s.author?.username||'member')}</button>`).join('')}</div>
<div class="card"><form id="postForm" class="composer"><div>${avatar(me.avatar,me.username)}</div><div class="composer-main"><textarea name="text" placeholder="What's on your mind, ${esc(me.displayName||me.username)}?"></textarea><div class="composer-actions"><label class="subtle-btn" style="margin:0;cursor:pointer">▧ Photo/video<input type="file" name="media" accept="image/*,video/mp4,video/webm,video/quicktime" hidden></label><select name="mediaFilter" aria-label="Media filter" class="media-filter-select"><option value="none">Original</option><option value="vivid">Vivid</option><option value="warm">Warm</option><option value="cool">Cool</option><option value="mono">Mono</option><option value="vintage">Vintage</option></select><button class="btn primary">Publish post</button></div></div></form><div id="postUploadProgress" class="upload-progress hidden" aria-live="polite"></div></div>
<div class="feed-filter-row"><b>Recent posts</b><select id="feedFilter" aria-label="Filter posts"><option value="all">All posts</option><option value="image">Photos</option><option value="video">Videos</option><option value="text">Text only</option></select></div><div id="feedPosts">${(adData.ads||[]).map(sponsoredCard).join('')}${window.chathsiPosts.map(postCard).join('')||'<div class="empty"><strong>Your feed starts here.</strong>Share a thought or follow people to get connected.</div>'}</div>`;
$('#postForm').addEventListener('submit',createPost);$('#newPostTop').onclick=()=>$('#postForm textarea').focus();$('#addStory').onclick=showStoryModal;$('#feedFilter').onchange=e=>renderFilteredPosts(e.target.value);$$('[data-view-story]').forEach(b=>b.onclick=()=>viewStory(Number(b.dataset.viewStory)));wirePostActions();wireAdActions();}
function renderFilteredPosts(filter='all'){const posts=window.chathsiPosts||[];const filtered=posts.filter(p=>filter==='all'||(filter==='text'?!p.mediaUrl:(p.mediaType||'image')===filter));$('#feedPosts').innerHTML=filtered.map(postCard).join('')||'<div class="empty">No posts match this filter yet.</div>';wirePostActions();wireAdActions();}
function viewStory(index){const stories=window.chathsiStories||[];const story=stories[index];if(!story)return;const filter=` style="filter:${mediaFilterCss(story.mediaFilter)}"`;const media=story.mediaUrl?(story.mediaType==='video'?`<video class="story-view-media"${filter} src="${esc(story.mediaUrl)}" controls autoplay playsinline></video>`:`<img class="story-view-media"${filter} src="${esc(story.mediaUrl)}" alt="Story">`):'';openModal(`<div class="story-viewer"><div class="story-view-head">${avatar(story.author?.avatar,story.author?.username)}<b>@${esc(story.author?.username||'member')}</b><span>${timeAgo(story.createdAt)}</span></div>${media}<div class="story-view-caption">${esc(story.text||'')}</div><div class="story-view-actions"><button class="subtle-btn" type="button" id="storyPrev" ${index===0?'disabled':''}>Previous</button><button class="btn primary" type="button" id="storyNext" ${index>=stories.length-1?'disabled':''}>Next</button></div></div>`);$('#storyPrev')?.addEventListener('click',()=>viewStory(index-1));$('#storyNext')?.addEventListener('click',()=>viewStory(index+1));}

function sponsoredCard(a){setTimeout(()=>api('/ads/'+a.id+'/impression',{method:'POST',body:{}}).catch(()=>{}),0);return `<article class="card sponsored-card"><div class="post-head"><div><b>${esc(a.businessName)}</b><div class="post-handle">Sponsored · Advertisement</div></div><span class="pill">Sponsored</span></div><h3>${esc(a.headline)}</h3><p>${esc(a.body)}</p>${a.mediaUrl?`<img class="post-media" src="${esc(a.mediaUrl)}" alt="Advert from ${esc(a.businessName)}">`:''}<button class="btn primary" data-ad-click="${esc(a.id)}">Learn more</button><button class="action-btn" data-ad-report="${esc(a.id)}">Report advert</button></article>`}
function postCard(p){const liked=p.likes?.some(id=>String(id)===String(me.id));return `<article class="card" data-post="${p._id}"><div class="post-head">${avatar(p.author?.avatar,p.author?.username)}<div><div class="post-author">@${esc(p.author?.username||'member')}${p.author?.premium!=='free'?'<span class="premium-badge">✦ '+esc(p.author.premium.toUpperCase())+'</span>':''}</div><div class="post-handle">${esc(p.author?.displayName||'CHATHSI member')}</div></div><span class="post-time">${timeAgo(p.createdAt)}</span></div>${p.text?`<div class="post-text">${esc(p.text)}</div>`:''}${p.mediaUrl?(p.mediaType==='video'?`<video class="post-media post-video" style="filter:${mediaFilterCss(p.mediaFilter)}" src="${esc(p.mediaUrl)}" controls playsinline preload="metadata"></video>`:`<img class="post-media" style="filter:${mediaFilterCss(p.mediaFilter)}" src="${esc(p.mediaUrl)}" alt="Post image">`):''}<div class="post-stats">${p.likes?.length||0} likes · ${p.comments?.length||0} comments</div><div class="post-actions"><button class="action-btn ${liked?'liked':''}" data-like="${p._id}">${liked?'♥':'♡'} Like</button><button class="action-btn" data-comment-focus="${p._id}">▢ Comment</button><button class="action-btn" data-share="${p._id}">↗ Share</button><button class="action-btn" data-report="${p._id}">⚑ Report</button></div><div class="comments">${(p.comments||[]).slice(-3).map(c=>`<div class="muted" style="margin-top:8px"><b>@${esc(c.author?.username||'member')}</b> ${esc(c.text)}</div>`).join('')}<form class="comment-row" data-comment="${p._id}"><input name="text" placeholder="Write a comment…" maxlength="1000" required><button class="btn primary">Send</button></form></div></article>`}
function wireAdActions(){
  $$('[data-ad-click]').forEach(b=>b.onclick=async()=>{try{const d=await api('/ads/'+b.dataset.adClick+'/click',{method:'POST',body:{}});window.open(d.url,'_blank','noopener,noreferrer')}catch(e){toast(e.message)}});
  $$('[data-ad-report]').forEach(b=>b.onclick=()=>{
    const id=b.dataset.adReport;
    openModal(`<h2>Report advert</h2><form id="adReportForm"><label>Reason<textarea name="reason" maxlength="500" required></textarea></label><button class="btn primary full">Submit report</button></form>`);
    $('#adReportForm').onsubmit=async e=>{e.preventDefault();try{await api('/ads/'+id+'/report',{method:'POST',body:{reason:new FormData(e.target).get('reason')}});closeModal();toast('Advert report submitted.')}catch(err){toast(err.message)}};
  });
}
async function renderAds(){const d=await api('/advertiser/campaigns');$('#page').innerHTML=`<h1 class="page-title">CHATHSI Ads Manager</h1><p class="page-sub">Promote a business or project. Every campaign is reviewed before it can appear.</p><div class="card"><h3>Create an advert</h3><form id="adCampaignForm" class="grid-2"><label>Business / organisation name<input name="businessName" maxlength="80" required></label><label>Advert headline<input name="headline" maxlength="100" required></label><label style="grid-column:1/-1">Advert description<textarea name="body" maxlength="500" required></textarea></label><label>Destination website (HTTPS only)<input name="destinationUrl" type="url" placeholder="https://example.com" required></label><label>Campaign budget (NGN)<input name="budget" type="number" min="1000" step="100" required></label><label>Start date<input name="startsAt" type="datetime-local" required></label><label>End date<input name="endsAt" type="datetime-local" required></label><label>Placement<select name="placement"><option value="feed">Main feed</option></select></label><label>Image / video (optional)<input type="file" name="media" accept="image/jpeg,image/png,image/gif,image/webp,video/mp4,video/webm"></label><p class="muted" style="grid-column:1/-1">Minimum budget ₦1,000. Payment is not collected automatically. Submit the campaign, follow the admin's payment instructions, and wait for approval. Ads must be suitable for a teen audience; prohibited categories include gambling, alcohol, nicotine, drugs, weapons and adult content. No sensitive-interest targeting is offered.</p><div id="adUploadProgress" class="upload-progress hidden" style="grid-column:1/-1" aria-live="polite"></div><button class="btn primary" style="grid-column:1/-1">Submit campaign for review</button></form></div><div class="card"><h3>Your campaigns</h3>${(d.campaigns||[]).map(a=>`<div class="list-row"><div><b>${esc(a.headline)}</b><div class="muted">${esc(a.businessName)} · ${esc(a.status)} · Payment: ${esc(a.paymentStatus)}</div><small>${Number(a.impressions||0)} impressions · ${Number(a.clicks||0)} clicks</small></div><b>${money(a.budget)}</b></div>`).join('')||'<p class="muted">You have not submitted a campaign yet.</p>'}</div>`;$('#adCampaignForm').onsubmit=async e=>{e.preventDefault();try{await uploadApi('/advertiser/campaigns',new FormData(e.target),p=>setUploadProgress($('#adUploadProgress'),p,'Uploading campaign media'));toast('Campaign submitted for admin review.');renderAds()}catch(err){toast(err.message)}}}
function wirePostActions(){$$('[data-like]').forEach(b=>b.onclick=async()=>{try{await api(`/posts/${b.dataset.like}/like`,{method:'POST'});await renderFeed()}catch(e){toast(e.message)}});$$('[data-comment]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api(`/posts/${f.dataset.comment}/comments`,{method:'POST',body:{text:new FormData(f).get('text')}});await renderFeed()}catch(err){toast(err.message)}});$$('[data-comment-focus]').forEach(b=>b.onclick=()=>document.querySelector(`[data-comment="${b.dataset.commentFocus}"] input`)?.focus());$$('[data-share]').forEach(b=>b.onclick=()=>{const url=location.origin+'/#post-'+b.dataset.share;navigator.clipboard?.writeText(url);toast('Post link copied (where clipboard is available).')});$$('[data-report]').forEach(b=>b.onclick=()=>openModal(`<h2>Report post</h2><form id="reportForm" data-post-id="${b.dataset.report}"><label>Why are you reporting this?<textarea name="reason" required maxlength="500"></textarea></label><button class="btn primary full">Submit report</button></form>`));const rf=$('#reportForm');if(rf)rf.onsubmit=async e=>{e.preventDefault();const id=rf.dataset.postId;try{await api(`/posts/${id}/report`,{method:'POST',body:{reason:new FormData(rf).get('reason')}});closeModal();toast('Report submitted for review.')}catch(err){toast(err.message)}};}
async function createPost(e){e.preventDefault();const form=e.currentTarget,fd=new FormData(form),file=form.querySelector('input[type=file]')?.files?.[0],btn=form.querySelector('button[type=submit]')||form.querySelector('button.primary'),progress=$('#postUploadProgress');if(file&&file.size>50*1024*1024){toast('Choose a file smaller than 50 MB.');return}if(btn){btn.disabled=true;btn.textContent='Uploading…'}try{await uploadApi('/posts',fd,p=>setUploadProgress(progress,p,file?.type.startsWith('video/')?'Uploading video':'Uploading media'));toast('Post published.');await renderFeed()}catch(err){toast(err.message)}finally{if(btn){btn.disabled=false;btn.textContent='Publish post'}if(progress)progress.classList.add('hidden')}}
function showStoryModal(){openModal(`<h2>Create a story</h2><form id="storyForm"><label>Caption<textarea name="text" maxlength="500" placeholder="Add a thought…"></textarea></label><label>Photo or video<input type="file" name="media" accept="image/*,video/mp4,video/webm,video/quicktime"></label><label>Creative filter<select name="mediaFilter"><option value="none">Original</option><option value="vivid">Vivid</option><option value="warm">Warm</option><option value="cool">Cool</option><option value="mono">Mono</option><option value="vintage">Vintage</option></select></label><p class="muted">Stories disappear after 24 hours. Video limit: 50 MB.</p><div id="storyUploadProgress" class="upload-progress hidden" aria-live="polite"></div><button class="btn primary full" id="storySubmit">Share story · 24 hours</button></form>`);$('#storyForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=$('#storySubmit');button.disabled=true;button.textContent='Uploading…';try{const result=await uploadApi('/stories',new FormData(form),p=>setUploadProgress($('#storyUploadProgress'),p,'Uploading story'));if(!result.story)throw new Error('The server did not confirm the story.');closeModal();toast('Story shared for 24 hours.');await renderFeed()}catch(err){toast(err.message);button.disabled=false;button.textContent='Share story · 24 hours'}}}
async function renderExplore(){const [d,f]=await Promise.all([api('/users'),api('/friends')]);cachedUsers=d.users;$('#page').innerHTML=`<h1 class="page-title">Explore & Friends</h1><p class="page-sub">Find people, send friend requests and build your circle.</p><div class="card"><h3>Friend requests (${f.incoming.length})</h3>${f.incoming.map(r=>`<div class="list-row"><b>@${esc(r.user.username)}</b><span><button class="btn primary" data-friend-accept="${r.id}">Accept</button> <button class="subtle-btn" data-friend-decline="${r.id}">Decline</button></span></div>`).join('')||'<p class="muted">No pending requests.</p>'}<h3>Your friends (${f.friends.length})</h3>${f.friends.map(r=>`<div class="list-row">@${esc(r.user.username)} <span>${statusMarkup(r.user.isOnline)}</span></div>`).join('')||'<p class="muted">Your accepted friends will appear here.</p>'}<p class="muted">Sent requests: ${f.outgoing.map(r=>'@'+esc(r.user.username)).join(', ')||'None'}</p></div><div class="card"><input id="peopleSearch" placeholder="Search by name or username…"></div><div id="peopleList">${userList(d.users)}</div>`;$('#peopleSearch').oninput=async e=>{const x=await api('/users?q='+encodeURIComponent(e.target.value));$('#peopleList').innerHTML=userList(x.users);wirePeopleActions()};wirePeopleActions();$$('[data-friend-accept],[data-friend-decline]').forEach(b=>b.onclick=async()=>{try{await api('/friends/'+(b.dataset.friendAccept||b.dataset.friendDecline)+'/respond',{method:'POST',body:{action:b.dataset.friendAccept?'accept':'decline'}});renderExplore()}catch(e){toast(e.message)}});}
function userList(users){return users.map(u=>`<div class="card row-between"><div class="row">${avatar(u.avatar,u.username)}<div><b>@${esc(u.username)}</b><div class="muted">${esc(u.displayName||'')} · <span data-user-status="${esc(u.id)}">${statusMarkup(u.isOnline)}</span></div></div></div><div class="row"><button class="subtle-btn" data-message="${u.id}">Message</button><button class="btn primary" data-follow="${u.id}">Follow</button><button class="subtle-btn" data-add-friend="${u.id}">＋ Add friend</button></div></div>`).join('')||'<div class="empty">No people found.</div>'}
function wirePeopleActions(){ $$('[data-add-friend]').forEach(b=>b.onclick=async()=>{try{await api('/friends/request/'+b.dataset.addFriend,{method:'POST'});b.textContent='Request sent';b.disabled=true;toast('Friend request sent.')}catch(e){toast(e.message)}}); }
document.addEventListener('click',async e=>{const f=e.target.closest('[data-follow]');if(f){try{const d=await api(`/users/${f.dataset.follow}/follow`,{method:'POST'});f.textContent=d.following?'Following':'Follow';toast(d.following?'Following':'Unfollowed')}catch(err){toast(err.message)}}const m=e.target.closest('[data-message]');if(m){activeChat=m.dataset.message;navigate('messages')}});
async function renderMessages(){
  const [c, people, gd] = await Promise.all([api('/conversations'), api('/users'), api('/groups')]);
  const conversations=c.conversations||[], groups=gd.groups||[];
  const known=new Set(conversations.map(x=>String(x.user.id)));
  const rows=[...(people.users||[]).filter(u=>!known.has(String(u.id))).slice(0,12)];
  $('#page').innerHTML=`<div class="row-between"><div><h1 class="page-title">Messages</h1><p class="page-sub">Private conversations and your group chats.</p></div><button class="btn primary" id="createGroupBtn">＋ Create group</button></div><div class="chat-layout"><div class="chat-users"><b>Recent chats</b>${conversations.map(x=>{const u=x.user;return `<div class="chat-user ${activeChat===String(u.id)&&!activeGroupId?'active':''}" data-chat-user="${esc(u.id)}"><div class="row-between"><span>@${esc(u.username)} <span data-user-status="${esc(u.id)}">${statusMarkup(u.isOnline)}</span></span>${x.unread?`<small class="pill">${x.unread}</small>`:''}</div>${x.lastMessage?`<small class="muted">${x.lastMessage.audioUrl?'Voice message':esc(x.lastMessage.text).slice(0,42)}</small>`:''}</div>`}).join('')||'<p class="muted">No private conversations yet.</p>'}<b style="display:block;margin-top:15px">Your groups</b>${groups.map(g=>`<div class="chat-user ${activeGroupId===String(g.id)?'active':''}" data-group-chat="${esc(g.id)}"><b>👥 ${esc(g.name)}</b><small class="muted">${g.memberCount} members${g.lastMessage?.text?' · '+esc(g.lastMessage.text).slice(0,30):''}</small></div>`).join('')||'<p class="muted">You have not joined a group yet.</p>'}<b style="display:block;margin-top:15px">Find people</b>${rows.map(u=>`<div class="chat-user" data-chat-user="${esc(u.id)}">@${esc(u.username)} <span data-user-status="${esc(u.id)}">${statusMarkup(u.isOnline)}</span></div>`).join('')}</div><div class="chat-window" id="chatWindow"><div class="empty"><strong>Select a conversation</strong>Choose a private chat or group to get started.</div></div></div>`;
  $('#createGroupBtn').onclick=()=>showCreateGroupModal(people.users||[]);
  $$('[data-chat-user]').forEach(b=>b.onclick=()=>{activeGroupId=null;activeChat=String(b.dataset.chatUser);renderMessages().then(()=>renderChatMessages(activeChat))});
  $$('[data-group-chat]').forEach(b=>b.onclick=()=>{activeChat=null;activeGroupId=String(b.dataset.groupChat);renderMessages().then(()=>renderGroupMessages(activeGroupId))});
  if(activeGroupId)renderGroupMessages(activeGroupId);else if(activeChat)renderChatMessages(activeChat);
}
function showCreateGroupModal(users=[]){
  openModal(`<h2>Create a group chat</h2><p class="muted">Start a conversation with up to 49 other CHATHSI members.</p><form id="createGroupForm"><label>Group name<input name="name" maxlength="60" required placeholder="e.g. Weekend Crew"></label><label>Description<textarea name="description" maxlength="240" placeholder="What is this group about?"></textarea></label><label>Add members <small class="muted">Enter usernames separated by commas</small><input name="usernames" placeholder="jane, alex, sam"></label><button class="btn primary full">Create group</button></form>`);
  $('#createGroupForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const usernames=String(f.get('usernames')||'').split(',').map(x=>x.trim().replace(/^@/, '')).filter(Boolean);try{const d=await api('/groups',{method:'POST',body:{name:f.get('name'),description:f.get('description'),usernames}});closeModal();activeChat=null;activeGroupId=String(d.group.id);toast('Group created!');await renderMessages();}catch(err){toast(err.message)}};
}
async function renderGroupMessages(id){if(!id)return;try{const d=await api('/groups/'+id+'/messages');const g=d.group;const w=$('#chatWindow');if(!w)return;w.innerHTML=`<div class="chat-header"><div><b>👥 ${esc(g.name)}</b><small class="muted" style="display:block">${g.memberCount} members</small></div><div class="row"><button class="subtle-btn" id="groupInfoBtn">Group info</button><button class="subtle-btn" id="leaveGroupBtn">Leave</button></div></div><div class="chat-messages" id="chatMessages">${d.messages.map(m=>`<div class="bubble ${String(m.sender?._id)===String(me.id)?'mine':''}">${String(m.sender?._id)!==String(me.id)?`<small style="display:block;font-weight:800">@${esc(m.sender?.username||'member')}</small>`:''}${m.messageType==='sticker'?`<div class="chat-sticker" role="img" aria-label="Sticker">${esc(m.text)}</div>`:m.mediaUrl?(m.mediaType==='video'?`<video controls playsinline src="${esc(m.mediaUrl)}" style="max-width:100%;border-radius:9px"></video>`:`<img src="${esc(m.mediaUrl)}" alt="Shared image" style="max-width:100%;border-radius:9px">`):''}${m.text&&m.messageType!=='sticker'?`<div>${esc(m.text)}</div>`:''}<small style="display:block;opacity:.7;margin-top:4px">${timeAgo(m.createdAt)}</small></div>`).join('')||'<div class="empty">This group is ready. Send the first message!</div>'}</div><form id="groupSend" class="chat-send"><input name="text" placeholder="Message the group…" maxlength="4000"><label class="subtle-btn" style="white-space:nowrap">＋ Media<input type="file" name="media" accept="image/*,video/mp4,video/webm,video/quicktime" hidden></label><button type="button" class="btn subtle-btn" id="openGroupStickers" aria-label="Open sticker picker">☺ Stickers</button><button class="btn primary">Send</button></form><div id="groupStickerPicker" class="sticker-picker hidden" aria-label="Group sticker library"></div>`;loadStickerPicker(id,true);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;
  $('#groupSend').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);if(!String(fd.get('text')||'').trim()&&!fd.get('media')?.size)return toast('Write a message or attach media.');try{await api('/groups/'+id+'/messages',{method:'POST',body:fd});await renderGroupMessages(id)}catch(err){toast(err.message)}};
  $('#groupInfoBtn').onclick=()=>showGroupInfo(g);
  $('#leaveGroupBtn').onclick=async()=>{if(!confirm('Leave this group?'))return;try{await api('/groups/'+id+'/leave',{method:'POST',body:{}});activeGroupId=null;toast('You left the group.');renderMessages()}catch(err){toast(err.message)}};
 }catch(e){toast(e.message)}}
function showGroupInfo(g){const controls=g.isAdmin?g.members.filter(m=>String(m.id)!==String(g.owner)).map(m=>`<div class="list-row"><div>${avatar(m.avatar,m.username)} <b>@${esc(m.username)}</b> ${g.admins.includes(String(m.id))?'<small class="pill">Admin</small>':''}</div><div class="row"><button class="subtle-btn" data-member-action="${esc(m.id)}" data-action="${g.admins.includes(String(m.id))?'demote':'promote'}">${g.admins.includes(String(m.id))?'Demote':'Make admin'}</button><button class="subtle-btn" data-member-action="${esc(m.id)}" data-action="remove">Remove</button></div></div>`).join(''):'';openModal(`<h2>${esc(g.name)}</h2><p class="muted">${esc(g.description||'No group description.')}</p><p><b>${g.memberCount} members</b></p>${g.members.map(m=>`<div class="list-row">${avatar(m.avatar,m.username)} <span>@${esc(m.username)} ${String(m.id)===String(g.owner)?'<small class="pill">Owner</small>':''}</span></div>`).join('')}${controls}${String(g.owner)===String(me.id)?'<button class="btn danger full" id="deleteGroupBtn" style="margin-top:12px">Delete group</button>':''}<form id="addGroupMember" style="margin-top:15px"><label>Add member by username<input name="username" placeholder="username" required></label><button class="btn primary full" ${g.isAdmin?'':'disabled'}>Add member</button></form>`);$('#deleteGroupBtn')?.addEventListener('click',async()=>{if(!confirm('Permanently delete this group and its messages?'))return;try{await api('/groups/'+g.id,{method:'DELETE'});closeModal();activeGroupId=null;toast('Group deleted.');renderMessages()}catch(err){toast(err.message)}});$('#addGroupMember').onsubmit=async e=>{e.preventDefault();try{await api('/groups/'+g.id+'/members',{method:'POST',body:Object.fromEntries(new FormData(e.target))});closeModal();toast('Member added.');renderMessages()}catch(err){toast(err.message)}};$$('[data-member-action]').forEach(b=>b.onclick=async()=>{try{await api('/groups/'+g.id+'/members/'+b.dataset.memberAction,{method:'PATCH',body:{action:b.dataset.action}});closeModal();toast('Group member updated.');renderMessages()}catch(err){toast(err.message)}})}
async function renderChatMessages(id){if(!id)return;const previousDraft=$('#chatSend input[name=text]')?.value||'';try{const d=await api('/messages/'+id);const w=$('#chatWindow');if(!w)return;w.innerHTML=`<div class="chat-header"><div class="row">${avatar(d.user.avatar,d.user.username)}<div><b>@${esc(d.user.username)}</b><div data-user-status="${esc(d.user.id)}">${statusMarkup(d.user.isOnline)}</div></div></div><div class="row call-button-group"><button class="btn primary call-button" id="startVoiceCall" ${activeCall?'disabled':''}>☎ Voice</button><button class="btn primary call-button" id="startVideoCall" ${activeCall?'disabled':''}>▣ Video</button></div></div><div class="chat-messages" id="chatMessages">${d.messages.map(m=>`<div class="bubble ${String(m.sender?._id)===String(me.id)?'mine':''}">${m.messageType==='sticker'?`<div class="chat-sticker" role="img" aria-label="Sticker">${esc(m.text)}</div>`:m.audioUrl?`<div class="voice-message"><audio controls preload="none" src="${esc(m.audioUrl)}"></audio><small>Voice message · ${Math.round(Number(m.audioDuration)||0)}s</small></div>`:esc(m.text)}</div>`).join('')}</div><form id="chatSend" class="chat-send"><input name="text" placeholder="Write a message…" maxlength="4000" required><button class="btn primary">Send</button><button type="button" class="btn subtle-btn" id="openStickers" aria-label="Open sticker picker">☺ Stickers</button><button type="button" class="btn subtle-btn" id="recordVoice">● Record</button></form><div id="stickerPicker" class="sticker-picker hidden" aria-label="Sticker library"></div><div class="voice-recording hidden" id="voiceRecording"><span id="recordStatus">Recording…</span><button class="btn primary" id="stopVoice">Stop & send</button><button class="btn subtle-btn" id="cancelVoice">Cancel</button></div>`;$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;const draftInput=$('#chatSend input[name=text]');if(draftInput)draftInput.value=previousDraft;loadStickerPicker(id,false);api('/streaks/'+id).then(st=>{const h=$('.chat-header');if(h){const el=document.createElement('span');el.className='streak-pill';el.textContent=`🔥 ${st.current} day streak`;el.title=`Best streak: ${st.best} days`;h.appendChild(el)}}).catch(()=>{});$('#startVoiceCall').onclick=()=>startCall(d.user,'audio');$('#startVideoCall').onclick=()=>startCall(d.user,'video');$('#chatSend').onsubmit=async e=>{e.preventDefault();const text=new FormData(e.target).get('text');try{await api('/messages/'+id,{method:'POST',body:{text}});const input=$('#chatSend input[name=text]');if(input)input.value='';await renderChatMessages(id)}catch(err){toast(err.message)}};wireVoiceRecorder(id)}catch(e){toast(e.message)}}
async function loadStickerPicker(id,isGroup){const open=$('#'+(isGroup?'openGroupStickers':'openStickers')),panel=$('#'+(isGroup?'groupStickerPicker':'stickerPicker'));if(!open||!panel)return;let stickers=[];try{stickers=(await api('/stickers')).stickers||[]}catch(e){return}open.onclick=()=>panel.classList.toggle('hidden');panel.innerHTML=`<div class="sticker-grid">${stickers.map(x=>`<button type="button" class="sticker-choice" data-sticker="${esc(x.id)}" aria-label="Send ${esc(x.label)} sticker" title="${esc(x.label)}">${esc(x.emoji)}</button>`).join('')}</div>`;panel.querySelectorAll('[data-sticker]').forEach(b=>b.onclick=async()=>{try{if(isGroup)await api('/groups/'+id+'/messages',{method:'POST',body:{stickerId:b.dataset.sticker}});else await api('/messages/'+id+'/sticker',{method:'POST',body:{stickerId:b.dataset.sticker}});panel.classList.add('hidden');if(isGroup)renderGroupMessages(id);else renderChatMessages(id)}catch(e){toast(e.message)}})}
function wireVoiceRecorder(recipientId){const recordBtn=$('#recordVoice');if(!recordBtn)return;let recorder=null,chunks=[],started=0,stream=null,cancelled=false;recordBtn.onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Voice recording is not supported by this browser.');stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/webm','audio/ogg'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);chunks=[];cancelled=false;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.start();started=Date.now();$('#voiceRecording').classList.remove('hidden');recordBtn.disabled=true;$('#stopVoice').onclick=()=>recorder?.stop();$('#cancelVoice').onclick=()=>{cancelled=true;if(recorder&&recorder.state!=='inactive')recorder.stop();chunks=[];stream?.getTracks().forEach(t=>t.stop());$('#voiceRecording').classList.add('hidden');recordBtn.disabled=false};recorder.onstop=async()=>{const duration=Math.min(600,Math.round((Date.now()-started)/1000));stream?.getTracks().forEach(t=>t.stop());recordBtn.disabled=false;$('#voiceRecording').classList.add('hidden');if(cancelled||!chunks.length)return;try{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});const fd=new FormData();fd.append('audio',blob,`voice-${Date.now()}.webm`);fd.append('duration',String(duration));await api('/messages/'+recipientId+'/voice',{method:'POST',body:fd});toast('Voice message sent.');renderChatMessages(recipientId)}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}}

async function renderNotifications(){const d=await api('/notifications');await api('/notifications/read',{method:'POST'});$('#page').innerHTML=`<h1 class="page-title">Notifications</h1><p class="page-sub">The latest activity around your account.</p><div class="card">${d.notifications.map(n=>`<div class="list-row"><div><b>${esc(n.text)}</b><div class="muted">${timeAgo(n.createdAt)} ago</div></div><span class="pill">${esc(n.type.replace('_',' '))}</span></div>`).join('')||'<div class="empty">No notifications yet.</div>'}</div>`}
async function renderWallet(){const [w,g]=await Promise.all([api('/wallet'),api('/gifts')]);cachedGifts=g.gifts;$('#page').innerHTML=`<h1 class="page-title">Wallet & gifts</h1><p class="page-sub">Your CHATHSI credits and virtual gift collection.</p><div class="wallet-balance"><small>AVAILABLE CHATHSI CREDITS</small><h2>${money(w.balance)}</h2><p>Platform credits only · Not withdrawable cash</p><div class="row" style="margin-top:18px"><button class="btn light-btn" id="topupOpen">＋ Request top-up</button><button class="btn" style="background:#ffffff22;color:white" id="giftTransferOpen">↗ Transfer a gift</button></div></div>
<div class="section-head"><b>Gift shop</b><span class="muted">Buy gifts with your credits</span></div><div class="grid-2">${g.gifts.map(x=>`<div class="gift-tile"><div class="gift-emoji">${esc(x.emoji)}</div><b>${esc(x.name)}</b><small>${money(x.value)} · ${esc(x.description)}</small><button class="btn primary" data-buy-gift="${x._id}">Get gift</button></div>`).join('')}</div>
<div class="card" style="margin-top:16px"><div class="section-head"><b>Your gift inventory</b><span class="muted">${w.gifts.length} items</span></div>${w.gifts.map(i=>`<div class="list-row"><div class="row"><span style="font-size:23px">${esc(i.gift?.emoji||'🎁')}</span><div><b>${esc(i.gift?.name||'Gift')}</b><div class="muted">${money(i.originalValue)} · ${i.status}</div></div></div>${i.status==='available'?`<button class="subtle-btn" data-send-gift="${i._id}">Transfer</button>`:'<span class="pill pending">Pending</span>'}</div>`).join('')||'<p class="muted">No gifts yet. Visit the gift shop to get started.</p>'}</div>
<div class="card"><b>Recent wallet activity</b>${w.ledger.map(l=>`<div class="list-row"><div><b>${esc(l.description)}</b><div class="muted">${timeAgo(l.createdAt)} ago</div></div><b style="color:${l.amount>=0?'#16834a':'#c35b52'}">${l.amount>=0?'+':''}${money(l.amount)}</b></div>`).join('')||'<p class="muted">Your transactions will appear here.</p>'}</div>`;
$('#topupOpen').onclick=()=>showTopupModal();$('#giftTransferOpen').onclick=()=>showTransferModal(w.gifts);$$('[data-buy-gift]').forEach(b=>b.onclick=async()=>{try{await api('/wallet/buy-gift',{method:'POST',body:{giftId:b.dataset.buyGift,quantity:1}});toast('Gift added to your inventory.');renderWallet()}catch(e){toast(e.message)}});$$('[data-send-gift]').forEach(b=>b.onclick=()=>showTransferModal(w.gifts,b.dataset.sendGift));}
async function showTopupModal(){const c=await api('/config');openModal(`<h2>Request wallet top-up</h2><p class="muted">All top-ups are reviewed by an administrator before credits are added.</p><form id="topupForm"><label>Amount (NGN)<input name="amount" type="number" min="100" max="10000000" required placeholder="e.g. 5000"></label><label>Payment method<select name="method">${c.paymentMethods.bankTransfer?'<option value="bank_transfer">Bank transfer</option>':''}${c.paymentMethods.card?'<option value="card">Card</option>':''}</select></label><div class="muted">${esc(c.paymentMethods.bankInstructions||'Payment instructions will be provided by the administrator.')}</div><label>Payment reference / proof link (optional)<input name="proofUrl" placeholder="Reference number or secure proof link"></label><button class="btn primary full">Submit for admin approval</button></form>`);$('#topupForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api('/wallet/topups',{method:'POST',body:{...d,amount:Number(d.amount)}});closeModal();toast('Top-up request submitted. Wallet is unchanged until approval.');}catch(err){toast(err.message)}}}
function showTransferModal(items,chosen=''){const available=items.filter(i=>i.status==='available');openModal(`<h2>Transfer a gift</h2><p class="muted">Every transfer requires admin approval. On approval, the recipient receives 100% of the gift's configured value as CHATHSI credits and the gift is consumed.</p><form id="transferForm"><label>Recipient username<input name="username" required placeholder="username"></label><label>Gift<select name="giftItemId" required>${available.map(i=>`<option value="${i._id}" ${i._id===chosen?'selected':''}>${esc(i.gift?.emoji||'🎁')} ${esc(i.gift?.name||'Gift')} · ${money(i.originalValue)}</option>`).join('')}</select></label><button class="btn primary full" ${available.length?'':'disabled'}>Request transfer</button></form>`);$('#transferForm').onsubmit=async e=>{e.preventDefault();try{await api('/wallet/gift-transfer',{method:'POST',body:Object.fromEntries(new FormData(e.target))});closeModal();toast('Transfer sent to admin for approval.');renderWallet()}catch(err){toast(err.message)}}}
async function renderProfile(){const d=await api('/posts');const mine=d.posts.filter(p=>String(p.author?._id)===String(me.id));$('#page').innerHTML=`<div class="card" style="padding:0;overflow:hidden"><div class="profile-hero"></div><div class="profile-info">${avatar(me.avatar,me.username)}<div class="profile-name">${esc(me.displayName||me.username)} ${me.premium!=='free'?'<span class="premium-badge">✦ '+me.premium.toUpperCase()+'</span>':''}</div><div class="muted">@${esc(me.username)}</div><p class="profile-bio">${esc(me.bio||'No bio added yet.')}</p><div class="stat-row"><span><b>${me.followersCount}</b> followers</span><span><b>${me.followingCount}</b> following</span><span><b>${mine.length}</b> posts</span></div><button class="subtle-btn" id="editProfile" style="margin-top:15px">Edit profile</button></div></div><h3>Your posts</h3>${mine.map(postCard).join('')||'<div class="empty">Your posts will appear here.</div>'}`;$('#editProfile').onclick=()=>openModal(`<h2>Edit profile</h2><form id="profileForm"><label>Display name<input name="displayName" maxlength="50" value="${esc(me.displayName)}"></label><label>Bio<textarea name="bio" maxlength="180">${esc(me.bio)}</textarea></label><label>Profile picture<input type="file" name="avatar" accept="image/jpeg,image/png,image/gif,image/webp"></label><div id="profileUploadProgress" class="upload-progress hidden" aria-live="polite"></div><button class="btn primary full" id="saveProfileBtn">Save profile</button></form>`);$('#modalContent')?.querySelector('#profileForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,file=form.querySelector('input[name=avatar]').files[0],btn=$('#saveProfileBtn'),progress=$('#profileUploadProgress');if(file&&file.size>12*1024*1024){toast('Profile picture must be smaller than 12 MB.');return}btn.disabled=true;btn.textContent='Saving…';try{const d=await uploadApi('/me',new FormData(form),p=>setUploadProgress(progress,p,'Uploading profile picture'),'PATCH');me=d.user;closeModal();await renderProfile();toast('Profile updated successfully.')}catch(err){toast(err.message)}finally{if(btn){btn.disabled=false;btn.textContent='Save profile'}}});wirePostActions();}
async function renderPremium(){const c=await api('/config');const plans=c.premiumPlans||[];$('#page').innerHTML=`<h1 class="page-title">CHATHSI Premium</h1><p class="page-sub">More ways to express yourself and grow your community.</p><div class="grid-2">${plans.map(p=>`<div class="premium-plan ${p.key==='pro'?'pro':''}"><span class="premium-badge">✦ ${p.key.toUpperCase()}</span><h3>${esc(p.name)}</h3><div class="premium-price">${money(p.price)}<small class="muted"> / month</small></div><ul>${p.benefits.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><button class="btn primary full" data-plan="${p.key}">Choose ${p.key.toUpperCase()}</button></div>`).join('')}</div><p class="muted" style="margin-top:16px">Membership checkout is not enabled in this starter. An administrator can configure plans; connect a verified payment provider before charging users.</p>`;$$('[data-plan]').forEach(b=>b.onclick=()=>toast('Premium checkout will be available after a verified payment integration is configured.'))}
async function renderAdmin(){if(me.role!=='admin'){toast('Admin access required.');return navigate('feed')}const [o,u,t,tr,g,r,ledger,adData]=await Promise.all([api('/admin/overview'),api('/admin/users'),api('/admin/topups'),api('/admin/transfers'),api('/admin/gifts'),api('/admin/reports'),api('/admin/ledger'),api('/admin/ads')]);const cfg=await api('/config');$('#page').innerHTML=`<h1 class="page-title">Admin control centre</h1><p class="page-sub">Manage CHATHSI users, payments, virtual gifts and platform operations.</p><div class="admin-grid">${[['Users',o.users],['Live posts',o.posts],['Pending top-ups',o.pendingTopups],['Pending gift transfers',o.pendingTransfers],['Open reports',o.openReports],['Ledger entries',o.ledgerEntries]].map(x=>`<div class="metric"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div>
<div class="admin-section card"><h3>Advert campaign approvals</h3><p class="muted">Review the creative and verify payment before approving. Only approved and paid campaigns can run.</p>${adData.ads.map(a=>`<div class="list-row"><div><b>${esc(a.businessName)} · ${esc(a.headline)}</b><div class="muted">${esc(a.advertiser?.username||'advertiser')} · Budget ${money(a.budget)} · ${esc(a.status)} / ${esc(a.paymentStatus)}</div><small>${esc(a.body)}</small></div><div class="row"><button class="subtle-btn" data-ad-review="${a._id}" data-status="rejected">Reject</button><button class="btn primary" data-ad-review="${a._id}" data-status="approved">Approve & verify payment</button></div></div>`).join('')||'<p class="muted">No submitted campaigns.</p>'}</div>
<div class="admin-section card"><h3>App name</h3><p class="muted">The default platform name is CHATHIS. Change the name displayed to everyone.</p><form id="platformNameForm" class="grid-2"><label>Application name<input name="name" maxlength="32" value="${esc(cfg.platform?.name||'CHATHIS')}" required></label><button class="btn primary" style="align-self:end">Save app name</button></form></div><div class="admin-section card"><h3>App appearance & special-event decorations</h3><p class="muted">Changes apply to everyone on CHATHIS, including users already online.</p><form id="appearanceSettings" class="grid-2"><label>Primary app colour<input type="color" name="primary" value="${esc(cfg.appearance?.primary||'#2878f0')}"></label><label>Secondary colour<input type="color" name="secondary" value="${esc(cfg.appearance?.secondary||'#4c9bff')}"></label><label>Page background<input type="color" name="background" value="${esc(cfg.appearance?.background||'#f5f8fc')}"></label><label>Card / panel colour<input type="color" name="surface" value="${esc(cfg.appearance?.surface||'#ffffff')}"></label><label>Main text colour<input type="color" name="text" value="${esc(cfg.appearance?.text||'#15233b')}"></label><label>App theme<select name="mode">${[['light','Light'],['dark','Dark'],['midnight','Midnight blue'],['rose','Rose']].map(x=>`<option value="${x[0]}" ${(cfg.appearance?.mode||'light')===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Special event decoration<select name="decoration">${[['none','No decoration'],['celebration','Celebration'],['christmas','Christmas'],['valentine','Valentine'],['halloween','Halloween'],['newyear','New Year'],['independence','Nigeria Independence']].map(x=>`<option value="${x[0]}" ${(cfg.appearance?.decoration||'none')===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label style="grid-column:1/-1">Event message / banner text<input name="eventLabel" maxlength="60" value="${esc(cfg.appearance?.eventLabel||'')}" placeholder="e.g. Happy Independence Day!"></label><button class="btn primary" style="grid-column:1/-1">Save app appearance</button></form><p class="muted">Decorations are visual only; no purchases or user data are affected.</p></div>
<div class="admin-section card"><h3>Payment methods & instructions</h3><form id="paymentSettings"><label><input style="width:auto" type="checkbox" name="bankTransfer" ${cfg.paymentMethods.bankTransfer?'checked':''}> Enable bank transfer</label><label><input style="width:auto" type="checkbox" name="card" ${cfg.paymentMethods.card?'checked':''}> Enable card request option</label><label>Bank transfer instructions<textarea name="bankInstructions">${esc(cfg.paymentMethods.bankInstructions||'')}</textarea></label><button class="btn primary">Save payment settings</button></form><p class="muted">All top-ups still require admin approval. Card option is a request placeholder until a verified provider checkout and webhook are integrated.</p></div>
<div class="admin-section card"><h3>Pending top-ups</h3>${t.topups.filter(x=>x.status==='pending').map(x=>`<div class="list-row"><div><b>${esc(x.user?.username||'user')} · ${money(x.amount)}</b><div class="muted">${esc(x.method)} · ${esc(x.reference)} · ${timeAgo(x.createdAt)}</div></div><div class="row"><button class="subtle-btn" data-topup="${x._id}" data-status="rejected">Reject</button><button class="btn primary" data-topup="${x._id}" data-status="approved">Approve</button></div></div>`).join('')||'<p class="muted">No pending top-ups.</p>'}</div>
<div class="admin-section card"><h3>Gift transfer approvals</h3>${tr.transfers.filter(x=>x.status==='pending').map(x=>`<div class="list-row"><div><b>@${esc(x.sender?.username)} → @${esc(x.recipient?.username)}</b><div class="muted">${esc(x.giftItem?.gift?.name||'Gift')} · ${money(x.value)}</div></div><div class="row"><button class="subtle-btn" data-transfer="${x._id}" data-status="rejected">Reject</button><button class="btn primary" data-transfer="${x._id}" data-status="approved">Approve</button></div></div>`).join('')||'<p class="muted">No pending transfers.</p>'}</div>
<div class="admin-section card"><h3>Gift catalogue</h3><form id="newGift" class="grid-2"><label>Gift name<input name="name" required></label><label>Emoji<input name="emoji" value="🎁" required></label><label>Value (NGN)<input name="value" type="number" min="1" required></label><label>Description<input name="description"></label><button class="btn primary">Create gift</button></form>${g.gifts.map(x=>`<div class="list-row"><div><b>${esc(x.emoji)} ${esc(x.name)}</b><div class="muted">${money(x.value)} · ${x.active?'Active':'Disabled'}</div></div><button class="subtle-btn" data-gift-toggle="${x._id}" data-active="${!x.active}">${x.active?'Disable':'Enable'}</button></div>`).join('')}<h3 style="margin-top:22px">Issue free gift (admin only)</h3><form id="issueGift" class="grid-2"><label>Username<input name="username" required></label><label>Gift<select name="giftId">${g.gifts.map(x=>`<option value="${x._id}">${esc(x.name)}</option>`).join('')}</select></label><label>Quantity<input name="quantity" type="number" min="1" max="100" value="1"></label><button class="btn primary">Issue gift</button></form></div>
<div class="admin-section card"><h3>User management</h3>${u.users.map(x=>`<div class="list-row"><div><b>@${esc(x.username)}</b><div class="muted">${esc(x.email)} · ${esc(x.role)} · ${esc(x.premium)}</div></div>${x.role==='admin'?'<span class="pill">Admin</span>':`<button class="subtle-btn" data-suspend="${x.id}" data-value="${!x.isSuspended}">${x.isSuspended?'Restore':'Suspend'}</button>`}</div>`).join('')}</div>
<div class="admin-section card"><h3>Reports</h3>${r.reports.filter(x=>x.status==='open').map(x=>`<div class="list-row"><div><b>${esc(x.targetType)} report</b><div class="muted">${esc(x.reason)}</div></div><button class="subtle-btn" data-report-resolve="${x._id}">Mark reviewed</button></div>`).join('')||'<p class="muted">No open reports.</p>'}</div>
<div class="admin-section card"><h3>Recent wallet ledger</h3>${ledger.ledger.slice(0,20).map(x=>`<div class="list-row"><div><b>@${esc(x.user?.username||'user')} · ${esc(x.description)}</b><div class="muted">${timeAgo(x.createdAt)} ago · ${esc(x.reference)}</div></div><b>${x.amount>=0?'+':''}${money(x.amount)}</b></div>`).join('')||'<p class="muted">No ledger entries yet.</p>'}</div>`;
$$('[data-ad-review]').forEach(b=>b.onclick=async()=>{if(b.dataset.status==='approved'&&!confirm('Confirm that payment has been received and the advert is suitable?'))return;try{await api('/admin/ads/'+b.dataset.adReview+'/review',{method:'POST',body:{status:b.dataset.status,paymentStatus:b.dataset.status==='approved'?'approved':'rejected'}});toast('Advert campaign reviewed.');renderAdmin()}catch(e){toast(e.message)}});
$('#platformNameForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/admin/platform',{method:'PATCH',body:Object.fromEntries(new FormData(e.target))});applyPlatformName(d.platform.name);toast('App name updated.')}catch(err){toast(err.message)}};
$('#appearanceSettings').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const d=await api('/admin/appearance',{method:'PATCH',body:f});applyAppearance(d.appearance);toast('App appearance updated for everyone.')}catch(err){toast(err.message)}};
$('#paymentSettings').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/admin/payment-methods',{method:'PATCH',body:{bankTransfer:f.has('bankTransfer'),card:f.has('card'),bankInstructions:f.get('bankInstructions')}});toast('Payment settings saved.')}catch(err){toast(err.message)}};
$('#newGift').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api('/admin/gifts',{method:'POST',body:{...f,value:Number(f.value)}});toast('Gift created.');renderAdmin()}catch(err){toast(err.message)}};
$('#issueGift').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api('/admin/gifts/issue',{method:'POST',body:{...f,quantity:Number(f.quantity)}});toast('Free gift issued.');renderAdmin()}catch(err){toast(err.message)}};
$$('[data-topup]').forEach(b=>b.onclick=async()=>{try{await api(`/admin/topups/${b.dataset.topup}/review`,{method:'POST',body:{status:b.dataset.status}});toast('Top-up reviewed.');renderAdmin()}catch(e){toast(e.message)}});
$$('[data-transfer]').forEach(b=>b.onclick=async()=>{try{await api(`/admin/transfers/${b.dataset.transfer}/review`,{method:'POST',body:{status:b.dataset.status}});toast('Gift transfer reviewed.');renderAdmin()}catch(e){toast(e.message)}});
$$('[data-gift-toggle]').forEach(b=>b.onclick=async()=>{try{await api(`/admin/gifts/${b.dataset.giftToggle}`,{method:'PATCH',body:{active:b.dataset.active==='true'}});renderAdmin()}catch(e){toast(e.message)}});
$$('[data-suspend]').forEach(b=>b.onclick=async()=>{try{await api(`/admin/users/${b.dataset.suspend}`,{method:'PATCH',body:{isSuspended:b.dataset.value==='true'}});renderAdmin()}catch(e){toast(e.message)}});
$$('[data-report-resolve]').forEach(b=>b.onclick=async()=>{try{await api(`/admin/reports/${b.dataset.reportResolve}/resolve`,{method:'POST',body:{status:'reviewed'}});renderAdmin()}catch(e){toast(e.message)}});
}
$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){navigate('explore').then(()=>{const s=$('#peopleSearch');if(s){s.value=e.target.value;s.dispatchEvent(new Event('input'))}})}});
boot();
